/*
 * ESP-NOW Dual LED Control — Board 1 (Sender)
 *
 * Reads D4 as a virtual button. When pressed, sends
 * LED_ON / LED_OFF commands to Board 2 via ESP-NOW.
 * Green LED on D2 blinks on each send.
 *
 * Circuit:
 *   D2 -> Green LED -> 220 ohm -> GND
 *   D4 -> Button (internal pull-up)
 */

#include <esp_now.h>
#include <WiFi.h>

// Board 2 MAC address
uint8_t receiverMAC[] = {0xAA, 0xBB, 0xCC, 0xDD, 0xEE, 0x02};

esp_now_peer_info_t peerInfo;

// Message types
#define CMD_LED_ON   1
#define CMD_LED_OFF  0

int lastButtonState = HIGH;

void onSendDone(const uint8_t *mac, esp_now_send_status_t status) {
  Serial.print("Send: ");
  Serial.println(status == ESP_NOW_SEND_SUCCESS ? "OK" : "FAIL");
}

void setup() {
  Serial.begin(9600);
  pinMode(2, OUTPUT);
  pinMode(4, INPUT_PULLUP);

  WiFi.mode(WIFI_STA);
  Serial.print("Sender MAC: ");
  Serial.println(WiFi.macAddress());

  esp_now_init();
  esp_now_register_send_cb(onSendDone);

  memcpy(peerInfo.peer_addr, receiverMAC, 6);
  peerInfo.channel = 0;
  peerInfo.encrypt = false;
  esp_now_add_peer(&peerInfo);

  Serial.println("Sender ready — press D4 to toggle remote LED");
}

void loop() {
  int btn = digitalRead(4);

  if (btn != lastButtonState) {
    lastButtonState = btn;

    int cmd = (btn == LOW) ? CMD_LED_ON : CMD_LED_OFF;
    esp_now_send(receiverMAC, (uint8_t *)&cmd, sizeof(cmd));

    // Blink green LED on send
    digitalWrite(2, HIGH);
    delay(50);
    digitalWrite(2, LOW);

    Serial.print("Sent command: ");
    Serial.println(cmd == CMD_LED_ON ? "LED_ON" : "LED_OFF");
  }

  delay(50);
}

