/*
 * ESP-NOW Dual LED Control — Board 2 (Receiver)
 *
 * Receives LED_ON / LED_OFF commands from Board 1.
 * Blue LED on D2 turns ON or OFF accordingly.
 *
 * Circuit:
 *   D2 -> Blue LED -> 220 ohm -> GND
 */

#include <esp_now.h>
#include <WiFi.h>

#define CMD_LED_ON   1
#define CMD_LED_OFF  0

void onRecvData(const uint8_t *mac, const uint8_t *data, int len) {
  if (len != sizeof(int)) return;
  int cmd = *(int *)data;

  digitalWrite(2, cmd == CMD_LED_ON ? HIGH : LOW);

  Serial.print("Received: ");
  Serial.print(cmd == CMD_LED_ON ? "LED_ON" : "LED_OFF");
  Serial.print(" from ");

  char macStr[18];
  snprintf(macStr, sizeof(macStr), "%02X:%02X:%02X:%02X:%02X:%02X",
           mac[0], mac[1], mac[2], mac[3], mac[4], mac[5]);
  Serial.println(macStr);
}

void setup() {
  Serial.begin(9600);
  pinMode(2, OUTPUT);
  digitalWrite(2, LOW);

  WiFi.mode(WIFI_STA);
  Serial.print("Receiver MAC: ");
  Serial.println(WiFi.macAddress());

  esp_now_init();
  esp_now_register_recv_cb(onRecvData);

  Serial.println("Receiver ready — waiting for commands...");
}

void loop() {
  delay(100);
}
